import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Link from 'flarum/common/components/Link';
/**
 * Friend-count badge next to the author's name in a post's header — same
 * `userViewItems` extension point PostUser exposes for Arena's stats
 * badge, so both extensions' badges sit in the same row.
 */
export default function addFriendBadgeToPost() {
  extend('flarum/forum/components/PostUser', 'userViewItems', function (items, user) {
    if (!user) return;
    if (app.forum.attribute('friendshipShowBadgeOnPost') === false) return;
    if (user.attribute('friendshipShowInPosts') === false) return;
    const count = user.attribute('friendCount') || 0;
    if (count === 0) return;
    const color = app.forum.attribute('friendshipBadgeColor') || '#84DCC6';
    const icon = app.forum.attribute('friendshipBadgeIcon') || 'fas fa-clipboard-user';
    items.add('friendCount', m(Link, {
      href: app.route('user.friendship', {
        username: user.username()
      }),
      className: "FriendshipPostBadge",
      style: {
        color
      }
    }, m("i", {
      className: icon
    }), m("span", {
      className: "FriendshipPostBadge-count"
    }, count)), 80);
  });
}